{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    required = ("nodes", "core_distance", "distances")
    for field in required:
        if field not in case:
            raise ValueError("missing required field: " + field)

    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list):
        raise ValueError("nodes must be a list")
    if any(not isinstance(node, str) for node in nodes):
        raise ValueError("node IDs must be strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node IDs must be unique")

    node_set = set(nodes)
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != node_set:
        raise ValueError("core_distance must contain exactly the registered nodes")

    cores = {}
    for node in nodes:
        value = core_distance[node]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError("core distances must be numeric")
        value = float(value)
        if not math.isfinite(value) or value < 0.0:
            raise ValueError("core distances must be finite and nonnegative")
        cores[node] = value

    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    reachability_edges = []
    seen_pairs = set()
    for entry in distances:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance must be a three-item sequence")
        left, right, distance = entry
        if not isinstance(left, str) or not isinstance(right, str):
            raise ValueError("distance endpoints must be strings")
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not a registered node")
        if left == right:
            raise ValueError("self distances are not valid edges")
        if isinstance(distance, bool) or not isinstance(distance, (int, float)):
            raise ValueError("distances must be numeric")
        distance = float(distance)
        if not math.isfinite(distance) or distance < 0.0:
            raise ValueError("distances must be finite and nonnegative")

        first, second = sorted((left, right))
        pair = (first, second)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance edge")
        seen_pairs.add(pair)
        weight = max(cores[first], cores[second], distance)
        reachability_edges.append((weight, first, second))

    reachability_edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    selected = []
    total_weight = 0.0
    target = max(0, len(nodes) - 1)
    for weight, left, right in reachability_edges:
        if union(left, right):
            selected.append([left, right, weight])
            total_weight += weight
            if len(selected) == target:
                break

    if len(selected) != target:
        raise ValueError("distance graph is disconnected")

    return {"edges": selected, "total_weight": total_weight}
"}
